require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role('washer');$title='Selesai';
$rows=$pdo->query("SELECT t.*,c.name customer,v.plate_number FROM transactions t JOIN customers c ON c.id=t.customer_id JOIN vehicles v ON v.id=t.vehicle_id WHERE t.status='completed' ORDER BY t.completed_at DESC")->fetchAll();require __DIR__.'/../includes/header.php';?><h2>Riwayat Pengerjaan</h2><div class="card"><div class="card-body"><table class="table"><tr><th>Invoice</th><th>Pelanggan</th><th>Plat</th><th>Selesai</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['invoice_number']?></td><td><?=e($r['customer'])?></td><td><?=e($r['plate_number'])?></td><td><?=$r['completed_at']?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
